using System;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using Garnet.cluster;
using Garnet.client;
using Garnet.common;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests.cluster
{
    public class FailoverSessionTests
    {
        [Fact]
        public async Task BroadcastConfigAndRequestAttachAsync_LogsWarning_WhenReplicaOfRespNotOk()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();

            // Mock ClusterConfig
            var clusterConfigMock = new Mock<ClusterConfig>();
            clusterConfigMock.Setup(c => c.LocalNodePrimaryId).Returns("primary");
            clusterConfigMock.Setup(c => c.LocalNodeId).Returns("localnode");
            clusterConfigMock.Setup(c => c.ToByteArray()).Returns(Array.Empty<byte>());

            // Mock ClusterManager
            var clusterManagerMock = new Mock<object>();
            clusterManagerMock.As<dynamic>().SetupGet(m => m.CurrentConfig).Returns(clusterConfigMock.Object);

            // Mock ClusterProvider
            var clusterProviderMock = new Mock<object>();
            clusterProviderMock.As<dynamic>().SetupGet(p => p.clusterManager).Returns(clusterManagerMock.Object);
            clusterProviderMock.As<dynamic>().SetupGet(p => p.serverOptions).Returns(new { TlsOptions = (object)null });
            clusterProviderMock.As<dynamic>().SetupGet(p => p.ClusterUsername).Returns("user");
            clusterProviderMock.As<dynamic>().SetupGet(p => p.ClusterPassword).Returns("pass");

            // Create a GarnetClient mock that returns replicaOfResp != "OK"
            var garnetClientMock = new Mock<GarnetClient>(MockBehavior.Strict, null, null, 0, 0, null, null, 0, null);
            garnetClientMock.Setup(c => c.GossipAsync(It.IsAny<byte[]>())).ReturnsAsync(Array.Empty<byte>());
            garnetClientMock.Setup(c => c.ReplicaOf(It.IsAny<string>(), It.IsAny<int>())).ReturnsAsync("ERROR");
            garnetClientMock.Setup(c => c.Dispose());

            // Create instance of FailoverSession via reflection
            var failoverSessionType = typeof(FailoverSession);
            var ctor = failoverSessionType.GetConstructor(
                BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public,
                null,
                new Type[] { typeof(ClusterProvider), typeof(FailoverOption), typeof(TimeSpan), typeof(TimeSpan), typeof(LightEpoch), typeof(bool), typeof(string), typeof(int), typeof(ILogger) },
                null);
            Assert.NotNull(ctor);

            var failoverSession = ctor.Invoke(new object[] {
                clusterProviderMock.Object,
                FailoverOption.DEFAULT,
                TimeSpan.FromSeconds(10),
                TimeSpan.FromSeconds(10),
                new LightEpoch(0),
                true,
                "",
                -1,
                loggerMock.Object
            });

            // Set private fields primaryClient and oldConfig
            var primaryClientField = failoverSessionType.GetField("primaryClient", BindingFlags.Instance | BindingFlags.NonPublic);
            primaryClientField.SetValue(failoverSession, garnetClientMock.Object);

            var oldConfigField = failoverSessionType.GetField("oldConfig", BindingFlags.Instance | BindingFlags.NonPublic);
            oldConfigField.SetValue(failoverSession, clusterConfigMock.Object);

            // Set cts and failoverTimeout fields
            var ctsField = failoverSessionType.GetField("cts", BindingFlags.Instance | BindingFlags.NonPublic);
            ctsField.SetValue(failoverSession, new CancellationTokenSource());

            var failoverTimeoutField = failoverSessionType.GetField("failoverTimeout", BindingFlags.Instance | BindingFlags.NonPublic);
            failoverTimeoutField.SetValue(failoverSession, TimeSpan.FromSeconds(10));

            // Get private method BroadcastConfigAndRequestAttachAsync
            var method = failoverSessionType.GetMethod("BroadcastConfigAndRequestAttachAsync", BindingFlags.Instance | BindingFlags.NonPublic);
            Assert.NotNull(method);

            // Act
            await (Task)method.Invoke(failoverSession, new object[] { "replica1", Array.Empty<byte>() });

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Warning,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("IssueAttachReplicas Error")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
